// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // The reference returns false for a non-existent interfaceId, the buggy version returns true
        bytes4 nonsenseId = 0xdeadbeef;
        bool refResult = c.supportsInterface(nonsenseId);
        // In the reference, supportsInterface returns false for interfaceId not IAccessControl or IERC165
        // The buggy version returns true for any interfaceId
        assertTrue(refResult == false, "Reference should return false for non-existent interfaceId");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Schedule an operation (needs proposer role, already has it)
        bytes32 salt = keccak256("test");
        c.schedule(address(this), 0, "", bytes32(0), salt, 1 days);
        // Cancel it to keep state clean for the later test
        bytes32 id = c.hashOperation(address(this), 0, "", bytes32(0), salt);
        c.cancel(id);
        // Now warp past the originally scheduled time (though cancelled, just to ensure no interference)
        vm.warp(block.timestamp + 2 days);
        // The divergence: supportsInterface returns false in P, true in M
        bool supports = c.supportsInterface(0xdeadbeef);
        // In reference P, this returns false; in mutant M it returns true
        assertTrue(supports == false, "Reference should return false for non-existent interface");
    }
}

