// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address proposer = address(0x123);
    bytes32 constant PROPOSER_ROLE = keccak256("PROPOSER_ROLE");

    function setUp() public {
        c = new C(0, proposer, address(this));
    }

    function testRegression_property() public {
        // Schedule an operation so there is something to cancel
        bytes32 id = c.hashOperation(address(this), 0, hex"", bytes32(0), bytes32(0));
        vm.prank(proposer);
        c.schedule(address(this), 0, hex"", bytes32(0), bytes32(0), 1);

        // Revoke PROPOSER_ROLE from proposer
        c.revokeRole(PROPOSER_ROLE, proposer);

        // Now proposer tries to cancel - should revert in reference, succeed in bug
        vm.prank(proposer);
        bool ok;
        try c.cancel(id) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: cancel reverts -> ok == false
        // Bug: cancel succeeds -> ok == true
        assertTrue(ok == false, "cancel should have reverted");
    }
}

