pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // schedule an operation with zero delay
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(0);
        address target = address(0x1234);
        uint256 value = 0;
        bytes memory data = "";
        uint256 delay = 0;
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // warp forward to make operation ready
        vm.warp(block.timestamp + 1);

        // try to execute the operation
        bool ok;
        try c.execute(target, value, data, predecessor, salt) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, the operation should execute successfully (ok == true)
        // In the buggy version, _afterCall reverts because hasRole returns true but the actual admin check fails
        assertTrue(ok, "execute should succeed");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Setup: give proposer and executor roles to this contract (address(this) is already timelock admin from setup)
        // The constructor already set our address(this) as TIMELOCK_ADMIN_ROLE
        // Grant PROPOSER_ROLE and EXECUTOR_ROLE to two different addresses
        address proposer = address(1);
        address executor = address(2);
        vm.startPrank(address(this));
        c.grantRole(c.PROPOSER_ROLE(), proposer);
        c.grantRole(c.EXECUTOR_ROLE(), executor);
        vm.stopPrank();

        // Proposer schedules an operation
        vm.prank(proposer);
        c.schedule(address(0), 0, "", bytes32(0), bytes32(0), 1);

        // Warp past delay
        vm.warp(block.timestamp + 2);

        // Executor tries to execute - only the reference allows it
        bool success;
        vm.prank(executor);
        try c.execute(address(0), 0, "", bytes32(0), bytes32(0)) {
            success = true;
        } catch {
            success = false;
        }

        // Reference: executor is not admin, so _afterCall reverts because hasRole(TIMELOCK_ADMIN_ROLE, executor) returns false
        // But in reference, hasRole correctly checks and returns false, causing execute to revert
        // However, in the buggy version, hasRole always returns true for admin check, so _afterCall passes
        // Wait - that would mean buggy version succeeds. Let me re-read...
        // Actually _afterCall requires having TIMELOCK_ADMIN_ROLE. In reference, executor doesn't have it, so revert.
        // In buggy version, hasRole always returns true, so it passes the admin check and completes.
        // So the reference reverts (success=false), buggy version succeeds (success=true).
        // We want to catch that divergence.

        assertTrue(!success, "Reference should revert when executor tries to complete without admin role");
    }
}

