pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Prepare a dummy target that does nothing
        address dummy = address(0x1234);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = keccak256("test");
        uint256 delay = 1;
        bytes32 id = c.hashOperation(dummy, value, data, predecessor, salt);

        // Proposer schedules the operation
        c.schedule(dummy, value, data, predecessor, salt, delay);

        // Warp past the delay so operation becomes ready
        vm.warp(block.timestamp + delay + 1);

        // Attempt to execute as a non-admin executor (address(0xBEEF))
        // The reference will revert in _afterCall because msg.sender lacks TIMELOCK_ADMIN_ROLE
        // The buggy version will succeed because hasRole always returns true
        address executor = address(0xBEEF);
        vm.deal(executor, 1 ether);
        vm.prank(executor);
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("execute(address,uint256,bytes,bytes32,bytes32)", dummy, value, data, predecessor, salt));

        // In the reference, execute reverts (ok false); in the buggy version, it succeeds (ok true)
        // We assert that the reference behavior is to revert
        assertTrue(!ok, "Reference should revert on execute by non-admin");
    }
}

