pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Set up a pending operation by scheduling
        bytes32 operationId = c.hashOperation(address(0xdead), 0, "", bytes32(0), bytes32(0x1234));
        c.schedule(address(0xdead), 0, "", bytes32(0), bytes32(0x1234), 0);
        // Warp to make the operation ready (delay is 0, already satisfied)
        vm.warp(block.timestamp + 1);
        // Now cancel the pending operation
        c.cancel(operationId);
        // In reference P, after cancel, _afterCall requires TIMELOCK_ADMIN_ROLE for the caller (this contract)
        // Since this contract has the admin role in P, it succeeds. In M, hasRole returns false, so _afterCall reverts.
        // Assert that the operation is cancelled (timestamp deleted = 0)
        assertTrue(c.getTimestamp(operationId) == 0);
    }
}

