        // But we can only deploy once in setUp. Use pre-deployed.

        // Redo: We have deployer with both roles.
        // Schedule another operation to cancel
        bytes32 id2 = c.hashOperation(address(1), 0, "", bytes32(0), bytes32(0x1234));
        c.schedule(address(1), 0, "", bytes32(0), bytes32(0x1234), 1);

        // Now try to renounce PROPOSER_ROLE from a non-owner
        // Buggy allows this, reference reverts
        bool renounceOk;
        try c.renounceRole(c.PROPOSER_ROLE(), address(this)) { renounceOk = true; } catch { renounceOk = false; }
        // In reference: renounce succeeds (self-only, address(this) == msg.sender)
        // In buggy: also succeeds (but buggy removed require)
        // Both succeed, no difference.

        // The difference is: buggy allows renouncing role of ANOTHER account.
        // So a third party can renounce PROPOSER from deployer.
        vm.prank(address(0xDEAD));
        bool thirdPartyRenounceOk;
        try c.renounceRole(c.PROPOSER_ROLE(), address(this)) { thirdPartyRenounceOk = true; } catch { thirdPartyRenounceOk = false; }

        // In reference: reverts (require self) -> thirdPartyRenounceOk = false
        // In buggy: succeeds -> thirdPartyRenounceOk = true

        // Now check cancel ability:
        // In reference: third party couldn't renounce, so address(this) still has PROPOSER -> can cancel
        // In buggy: third party could renounce, address(this) lost PROPOSER -> cannot cancel

        vm.prank(address(this));
