        try c.cancel(id2) { cancelOk = true; } catch { cancelOk = false; }

        // Reference: cancelOk = true (has role)
        // Buggy: cancelOk = false (lost role due to bogus renounce)

        assertTrue(cancelOk == true, "Reference: cancel should succeed; Bug: cancel should fail");
    }
