            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Reference should revert but buggy version succeeds");
    }

    function hashOperation(address target, uint256 value, bytes memory data, bytes32 predecessor, bytes32 salt) private pure returns (bytes32) {
        return keccak256(abi.encode(target, value, data, predecessor, salt));
    }
}

