pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Schedule an operation with delay 0
        address target = address(0x1234);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = keccak256("test");
        c.schedule(target, value, data, predecessor, salt, 0);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        // Warp past the execution time so the operation becomes ready
        vm.warp(block.timestamp + 1);
        // Now the operation is ready (timestamp == block.timestamp) and not done (timestamp != 1)
        // In reference: isOperationPending returns true (since timestamp > 1)
        // In bug: isOperationPending returns false (since timestamp >= 1 is true, but wait -- timestamp is >= 2? Actually block.timestamp+1 >= 2, so both would return true.
        // We need the boundary: timestamp exactly equals _DONE_TIMESTAMP (1) is impossible because we schedule with delay 0; the timestamp becomes block.timestamp which is >0.
        // Actually the difference: if an operation has timestamp 1 (done), isOperationPending must return false. But the bug makes it return true (since 1 >= 1 is true).
        // So we need to create a done operation (timestamp = 1) and then check isOperationPending.
        // But cancel requires isOperationPending to be true to revert. So we need an operation that is pending but not done: timestamp > 1.
        // The difference: if timestamp == 1, reference isOperationPending returns false, bug returns true.
        // So we need to get an operation with timestamp == 1. That happens after _afterCall sets _timestamps[id] = _DONE_TIMESTAMP (1).
        // Execute the operation to make it done:
        vm.prank(address(this)); // this contract is set up as proposer and executor
        c.execute(target, value, data, predecessor, salt);
        // Now the operation is done: timestamp = 1.
        // Now cancel should revert in reference because isOperationPending returns false (timestamp > 1? No, timestamp == 1, so false). Bug: isOperationPending returns true (1 >= 1 true), so cancel does NOT revert.
        bool cancelReverted;
        vm.prank(address(this)); // proposer role
        try c.cancel(id) {
            cancelReverted = false;
        } catch {
            cancelReverted = true;
        }
        // Reference: cancel reverts (cancelReverted == true). Bug: cancel succeeds (cancelReverted == false).
        assertTrue(cancelReverted);
    }
}

